import { z } from "../vendor/zod.js";
import { Id, IsoDate } from "./common.js";
// ── Product map (generated by `forge sync` — deterministic, never hand-written) ──
export const Surface = z.object({
    /** "page:/settings" or "endpoint:GET /api/users/:id" */
    id: z.string().min(1),
    kind: z.enum(["page", "endpoint"]),
    route: z.string(),
    method: z.string().optional(),
    /** Path relative to the project root. */
    file: z.string().min(1),
    framework: z.string().min(1),
    /** Node id in graphify-out/graph.json for this file, when a code graph exists. */
    graphifyNode: z.string().optional(),
});
export const ProductMap = z.object({
    version: z.literal(1),
    generatedAt: IsoDate,
    fingerprint: z.object({ files: z.number().int().min(0), hash: z.string().min(1) }),
    frameworks: z.array(z.string()),
    surfaces: z.array(Surface),
    /** A code file calls an endpoint (fetch/axios/… literal matched to a known route). */
    calls: z.array(z.object({ from: z.string(), to: z.string(), literal: z.string() })),
    docs: z.array(z.object({ path: z.string(), title: z.string(), bytes: z.number().int() })),
    graph: z.object({
        status: z.enum(["updated", "unchanged", "skipped", "unavailable", "failed"]),
        note: z.string().optional(),
    }),
});
// ── Product model (written by the product-cartographer, checked by the `understand` gate) ──
export const FeatureStatus = z.enum(["live", "partial", "placeholder", "broken", "unknown"]);
export const ProductModel = z.object({
    summary: z.string().min(1),
    stage: z.enum(["idea", "validation", "pmf-search", "growth", "scale", "pivot", "unknown"]),
    personas: z
        .array(z.object({ id: Id, name: z.string().min(1), jobs: z.array(z.string().min(1)).min(1) }))
        .min(1),
    features: z
        .array(z.object({
        id: Id,
        name: z.string().min(1),
        description: z.string().min(1),
        /** Surface ids from the product map that deliver this feature. */
        surfaces: z.array(z.string()).default([]),
        files: z.array(z.string()).default([]),
        status: FeatureStatus,
        /** Where the claim comes from: file paths, docs, graph nodes, tests. */
        evidence: z.array(z.string()).default([]),
        personas: z.array(Id).default([]),
    }))
        .min(1),
    /** Surfaces deliberately left out of the model (health checks, internal tools), with a reason. */
    ignoredSurfaces: z.array(z.object({ surface: z.string().min(1), reason: z.string().min(1) })).default([]),
    gaps: z
        .array(z.object({
        id: Id,
        description: z.string().min(1),
        severity: z.enum(["low", "medium", "high"]),
        feature: Id.optional(),
        surface: z.string().optional(),
    }))
        .default([]),
    facts: z.array(z.string()).default([]),
    assumptions: z.array(z.string()).default([]),
    openQuestions: z.array(z.string()).default([]),
});
// ── Page audit (pro-page-complete) ──
export const AtomStatus = z.enum(["live", "placeholder", "dead", "missing-join", "permission-wrong", "unknown"]);
export const AtomBreak = z.enum([
    "dead-control",
    "orphan-url",
    "placeholder-copy",
    "dropped-field",
    "mapper-lie",
    "mock-leftover",
    "permission-lie",
    "unconnected",
]);
const Check = z.enum(["ok", "gap", "n/a"]);
export const PageAudit = z.object({
    /** Route or URL of the page. */
    page: z.string().min(1),
    surface: z.string().optional(),
    who: z.string().min(1),
    job: z.string().min(1),
    trust: z.string().min(1),
    antiGoal: z.string().min(1),
    atoms: z
        .array(z.object({
        label: z.string().min(1),
        class: z.enum([
            "chrome",
            "navigation",
            "action",
            "input",
            "content",
            "people",
            "media",
            "conversation",
            "state",
            "feedback",
            "permission",
        ]),
        type: z.enum(["tab", "button", "input", "link", "card", "text", "media", "empty", "other"]),
        job: z.string().min(1),
        data: z.string().min(1),
        clickPath: z.string().min(1),
        status: AtomStatus,
        break: AtomBreak.optional(),
        /** API → DTO → mapper → render, as found during the trace. */
        trace: z.string().optional(),
        fix: z.string().optional(),
        /** Must be live before the page counts as complete. */
        must: z.boolean().default(false),
    }))
        .min(1),
    connections: z
        .array(z.object({ from: z.string().min(1), to: z.string().min(1), kind: z.enum(["already-exists", "small-join", "idea"]) }))
        .default([]),
    ideas: z.array(z.object({ idea: z.string().min(1), why: z.string().min(1), effort: z.enum(["S", "M", "L"]) })).default([]),
    robustness: z
        .object({
        empty: Check,
        error: Check,
        loading: Check,
        permissions: Check,
        stale: Check,
        smallScreen: Check,
        media: Check,
        destructive: Check,
    })
        .partial()
        .default({}),
    proof: z.array(z.string()).default([]),
    auditedAt: IsoDate,
});
